-- RBAC roles + role-rank enforcement helpers.
-- Generated by codegraph. DO NOT EDIT.


-- Extend the basejump.account_role enum with every configured hierarchy role.
-- Roles already present (basejump defaults) are skipped by the existence check.
DO $$
BEGIN

    IF NOT EXISTS (
        SELECT 1 FROM pg_enum
        WHERE enumtypid = 'basejump.account_role'::regtype
        AND enumlabel = 'owner'
    ) THEN
        ALTER TYPE basejump.account_role ADD VALUE 'owner';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_enum
        WHERE enumtypid = 'basejump.account_role'::regtype
        AND enumlabel = 'manager'
    ) THEN
        ALTER TYPE basejump.account_role ADD VALUE 'manager';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_enum
        WHERE enumtypid = 'basejump.account_role'::regtype
        AND enumlabel = 'member'
    ) THEN
        ALTER TYPE basejump.account_role ADD VALUE 'member';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_enum
        WHERE enumtypid = 'basejump.account_role'::regtype
        AND enumlabel = 'employee'
    ) THEN
        ALTER TYPE basejump.account_role ADD VALUE 'employee';
    END IF;

END $$;

-- Function to resolve current user's role within their organization
CREATE OR REPLACE FUNCTION public.get_current_account_role()
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $fn$
DECLARE
    v_org_id uuid;
    v_role text;
BEGIN
    v_org_id := COALESCE(
        public.get_current_org_id(),
        public.resolve_user_org(
            nullif(current_setting('app.user_id', true), '')::uuid
        )
    );
    IF v_org_id IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT account_role::text INTO v_role
    FROM basejump.account_user
    WHERE account_id = v_org_id
      AND user_id = nullif(current_setting('app.user_id', true), '')::uuid;

    IF v_role = 'member' THEN
        v_role := 'employee';
    END IF;

    RETURN v_role;
END;
$fn$;

GRANT EXECUTE ON FUNCTION public.get_current_account_role() TO authenticated;

-- Role ranking for the DB-level role policies (#169).
-- Roles earlier in the configured hierarchy outrank later ones; the basejump
-- 'member' role normalizes to 'employee' (basejump grants every org creator
-- 'member', which is the LEAST privileged role in this model). Unknown roles
-- rank last so they deny everything.
CREATE OR REPLACE FUNCTION public.role_rank(p_role text)
RETURNS int
LANGUAGE plpgsql STABLE
AS $fn$
DECLARE
    r TEXT;
BEGIN
    r := coalesce(p_role, '');
    IF r = 'member' THEN
        r := 'employee';
    END IF;

    IF r = 'owner' THEN
        RETURN 0;
    END IF;

    IF r = 'manager' THEN
        RETURN 1;
    END IF;

    IF r = 'member' THEN
        RETURN 2;
    END IF;

    IF r = 'employee' THEN
        RETURN 3;
    END IF;

    RETURN 9999;
END;
$fn$;

-- Minimum-role gate used by the RESTRICTIVE role_enforced_* RLS policies.
-- Pass-through:
-- - API-key sessions (role 'api_key') — their scopes are enforced by
--   public.enforce_api_key_scope in the same statement.
-- - Sessions without a role claim — tenancy-only tables keep their previous
--   behaviour.
-- Denial raises P0403 with a ROLE_FORBIDDEN payload, mapped to HTTP 403 by
-- the generated error classifier.
CREATE OR REPLACE FUNCTION public.role_at_least(p_min_role text)
 RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER
AS $function$
DECLARE
    v_role TEXT;
BEGIN
    v_role := coalesce(current_setting('app.role', true), '');
    IF v_role = '' OR v_role = 'api_key' THEN
        RETURN TRUE;
    END IF;
    IF public.role_rank(v_role) <= public.role_rank(p_min_role) THEN
        RETURN TRUE;
    END IF;
    RAISE EXCEPTION USING
        ERRCODE = 'P0403',
        MESSAGE = json_build_object('code', 'ROLE_FORBIDDEN', 'role', v_role, 'required', p_min_role)::text;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.role_rank(text) TO app_user, api_key;
GRANT EXECUTE ON FUNCTION public.role_at_least(text) TO app_user, api_key;
